#include <bits/stdc++.h>
using namespace std;

class Solution {
public:
    long long maxPoints(vector<int>& technique1, vector<int>& technique2, int k) {
        int n = technique1.size();
        long long ans = 0;
        vector<int> diff;
        for (int i = 0; i < n; ++i) {
            ans += technique2[i];
            diff.push_back(technique1[i] - technique2[i]);
        }
        sort(diff.rbegin(), diff.rend());
        for (int i = 0; i < n; ++i)
            if (i < k || diff[i] > 0) ans += diff[i];
        return ans;
    }
};
